// Shared sale workspace. All permissions and state transitions are verified by the API.
let salePortal=null,saleReviewFilter='all';
const reviewLabel=c=>({draft:'Rascunho',submitted:'Em análise',returned:'Devolvida',approved:'Aprovada'}[c.reviewStatus]||c.status||'Aprovada');
function saleList(list){return list.filter(c=>saleReviewFilter==='all'||(c.reviewStatus||'approved')===saleReviewFilter);}
function saleFilters(){return `<div class="filters"><label for="saleReviewFilter">Situação da venda</label><select id="saleReviewFilter" onchange="saleReviewFilter=this.value;render()">${Object.entries({all:'Todas',draft:'Rascunhos',submitted:'Em análise',returned:'Devolvidas',approved:'Aprovadas'}).map(([id,label])=>`<option value="${id}" ${saleReviewFilter===id?'selected':''}>${label}</option>`).join('')}</select></div>`;}
const priorPortalRender=render;
render=function(){priorPortalRender();if(!cloudReady)return;if(page==='Contratos'){const root=document.getElementById('app');if(!canManage()){root.innerHTML=title(moduleLabel('Contratos'),'Documentos, validação e acompanhamento de cada venda.',canSell()?btn('+ Nova venda','newSale()'):'')+saleFilters()+`<section class="panel"><input id="portalSaleSearch" type="search" aria-label="Buscar cliente ou contrato" placeholder="Buscar cliente ou contrato…" value="${esc(query)}" oninput="query=this.value;refreshPersonalSales()"><div id="mySales">${personalContracts(saleList(visible()).filter(c=>matchesContract(c,query)))}</div></section><p>Comissions</p>`;}else{const rows=document.getElementById('contractRows');if(rows){rows.parentElement.insertAdjacentHTML('afterbegin',saleFilters());}}}};
function refreshPersonalSales(){document.getElementById('mySales').innerHTML=personalContracts(saleList(visible()).filter(c=>matchesContract(c,query)));}
refreshContracts=function(){document.getElementById('contractRows').innerHTML=contractTable(saleList(visible()).filter(c=>matchesContract(c,query)));};
personalContracts=function(list){return table(['Contrato / cliente','Empresa / produto','Mensalidade / venda','Implementação','Situação'],list.map(c=>[`${contractReference(c)}<div>${esc(c.client)}</div>`,`${esc(companyName(c.company))}<div class="small">${esc(product(c.product)?.name||c.plan)}</div>`,money(c.monthly),money(c.setup),`<span class="pill">${esc(reviewLabel(c))}</span>`]));};
async function openSalePortal(id){if(!accessibleModules().includes('Contratos'))return toast('Módulo Contratos não liberado.');const c=state.contracts.find(c=>c.id===id);if(!c||!canAccess(c.company))return;try{const data=await api('portal-load',{contractId:id});salePortal={id,data,note:'',selections:{}};renderSalePortal();return true;}catch(e){toast(e.message);return false;}}
function portalItems(){const c=state.contracts.find(c=>c.id===salePortal?.id);return c?state.contracts.filter(x=>x.company===c.company&&(x.saleId||'legacy-'+x.id)===(c.saleId||'legacy-'+c.id)):[];}
function portalMessage(message,error=true){const el=document.getElementById('portalFeedback');if(el){el.textContent=message;el.classList.toggle('error',error);}else toast(message);}
function capturePortalForm(){if(!salePortal)return;salePortal.note=document.getElementById('portalNote')?.value||salePortal.note||'';for(const c of portalItems())for(const k of ['seller','dev','partner']){const el=document.getElementById('f_portal-'+k+'-'+c.id);if(el)salePortal.selections[c.id+'-'+k]=el.value;}for(const c of portalItems())for(const [key,prefix] of [['feePaidAt','confirmFee'],['setupPaidAt','confirmSetup']]){const el=document.getElementById('f_'+prefix+c.id);if(el)salePortal.selections[c.id+'-'+key]=el.value;}}
function renderSalePortal(){const {id,data}=salePortal,c=state.contracts.find(c=>c.id===id);if(!c)return;const items=portalItems(),m=document.getElementById('modal');m.classList.add('sale-portal');const canReview=data.manager&&data.reviewStatus==='submitted'&&!c.archived;const people=state.users.filter(u=>u.active&&(u.all||u.companies.includes(c.company)));m.innerHTML=`<div class="panelhead"><div><h2>${esc(c.client)}</h2><p>${esc(companyName(c.company))} · ${esc(contractCode(c))}</p></div><span class="pill">${esc(reviewLabel(c))}</span></div><div class="portal-items">${items.map(item=>`<section class="portal-item"><h3>${esc(product(item.product)?.name||item.plan)}</h3><p>${money(item.monthly)} · implementação ${item.setupWaived?'dispensada por negociação':money(item.setup)}</p>${saleReceiptSummary(item)}${canReview?`<div class="formgrid">${['seller','dev','partner'].map(k=>select('portal-'+k+'-'+item.id,({seller:'Vendedor',dev:'Desenvolvedor',partner:'Parceiro'})[k],[['','Não atribuído'],...people.map(u=>[u.id,u.name])],salePortal.selections[item.id+'-'+k]??item[k]??'')).join('')}</div>${canManage('Recebíveis')?`<div class="formgrid">${field('confirmFee'+item.id,'Confirmar recebimento do 1º fee',salePortal.selections[item.id+'-feePaidAt']??item.reportedFeePaidAt??'','date',`max="${localToday()}"`)}${item.setup>0&&!item.setupWaived?field('confirmSetup'+item.id,'Confirmar implementação · 1ª parcela',salePortal.selections[item.id+'-setupPaidAt']??item.reportedSetupPaidAt??'','date',`max="${localToday()}"`):''}</div><p class="small">Ao aprovar, estas datas confirmam cada recebimento separadamente. Deixe vazio o que ainda não recebeu.</p>`:`<p class="small">Datas informadas: 1º fee ${compactDate(item.reportedFeePaidAt)} · implementação ${compactDate(item.reportedSetupPaidAt)}. A confirmação fica em Recebíveis.</p>`}`:`<p class="small">Vendedor: ${esc(userName(item.seller))} · Desenvolvimento: ${esc(userName(item.dev))}</p>`}</section>`).join('')}</div><section class="portal-documents"><h3>Documentos da venda</h3>${!data.documentsReady?'<div class="notice">O envio de anexos aguarda a execução do SQL de documentos pelo administrador no Supabase. O rascunho permanece salvo.</div>':`${data.canEdit?'<label class="portal-upload">Adicionar contrato ou documento<input type="file" id="saleFiles" multiple accept="application/pdf,image/png,image/jpeg" onchange="uploadSaleDocuments(this.files)"></label><p class="small">PDF, JPG ou PNG · até 10 MB por arquivo. Os arquivos são privados.</p>':''}<ul class="portal-document-list">${data.documents.map(d=>`<li><div><strong>${esc(d.name)}</strong><span class="small">${esc(d.status==='ready'?'Recebido':d.status==='archived'?'Retirado · histórico preservado':'Envio não finalizado')} · ${Math.ceil(d.size_bytes/1024)} KB</span></div><div class="catalog-actions">${d.status==='ready'?btn('Baixar',`downloadSaleDocument('${actionId(d.id)}')`,true):d.status==='pending'&&d.uploaded_by===currentUser?btn('Finalizar envio',`finishSaleDocument('${actionId(d.id)}')`,true):''}${data.canEdit&&(data.manager||d.uploaded_by===currentUser)?(d.status==='archived'?btn('Restaurar',`restoreSaleDocument('${actionId(d.id)}')`,true):btn('Retirar',`archiveSaleDocument('${actionId(d.id)}')`,true)):''}</div></li>`).join('')||'<li>Nenhum documento enviado.</li>'}</ul>`}</section><section class="portal-conversation"><h3>Histórico e mensagens</h3><ol>${data.history.slice(-20).map(e=>`<li><strong>${esc(e.author||userName(e.by))}</strong> · ${esc(({submit:'Enviou para análise',approve:'Aprovou a venda',return:'Devolveu para correção',comment:'Mensagem','edit-draft':'Corrigiu o rascunho'})[e.action]||e.action)}<div class="small">${esc(new Date(e.at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}))}</div>${e.message?`<p>${esc(e.message)}</p>`:''}</li>`).join('')||'<li>O histórico desta venda começa aqui.</li>'}</ol><label for="portalNote">Mensagem para a empresa e participantes</label><textarea id="portalNote" maxlength="2000" rows="3" placeholder="Escreva uma observação ou o motivo de uma correção…">${esc(salePortal.note)}</textarea></section>${data.manager?contractHistoryPanel(c,data.changes||[]):''}<p id="portalFeedback" role="status" aria-live="polite"></p><div class="actions portal-actions">${btn('Fechar',"document.getElementById('modal').close()",true)}${!c.archived?btn('Enviar mensagem',"portalReview('comment')",true):''}${data.canEdit&&!data.manager&&['draft','returned'].includes(data.reviewStatus)?btn('Corrigir dados','editPortalDraft()',true)+btn('Enviar para análise',"portalReview('submit')"):''}${canReview?btn('Devolver para correção',"portalReview('return')",true)+btn('Aprovar venda',"portalReview('approve')"):''}${data.manager&&canManage('Recebíveis')&&(!c.reviewStatus||c.reviewStatus==='approved')?btn('Registrar recebimentos',`editContractReceipts(${contractIdLiteral(c.id)})`,true):''}${data.manager&&(!c.reviewStatus||c.reviewStatus==='approved')?btn('Editar contrato',`editContract(${contractIdLiteral(c.id)})`,true):''}</div>`;if(!m.open)m.showModal();}
async function refreshSalePortal(){capturePortalForm();const data=await api('portal-load',{contractId:salePortal.id});salePortal.data=data;renderSalePortal();}
async function portalReview(action){if(!salePortal||salePortal.busy)return;capturePortalForm();const id=salePortal.id,oldPage=page,oldCompany=company;try{salePortal.busy=true;portalMessage('Salvando…',false);const participants=portalItems().map(c=>({id:c.id,...Object.fromEntries(['seller','dev','partner'].map(k=>[k,salePortal.selections[c.id+'-'+k]??c[k]??''])),...(canManage('Recebíveis')?{feePaidAt:salePortal.selections[c.id+'-feePaidAt']||null,setupPaidAt:salePortal.selections[c.id+'-setupPaidAt']||null}:{})}));await api('sale-review',{contractId:id,version:cloudVersion,reviewAction:action,message:salePortal.note,participants});await loadCloud();page=oldPage;company=allowed().some(c=>c.id===oldCompany)?oldCompany:'all';render();await openSalePortal(id);portalMessage(action==='submit'?'Venda enviada. A empresa irá conferir os dados e os documentos.':action==='approve'?'Venda aprovada. Contratos, cobranças e comissões foram ativados.':action==='return'?'Venda devolvida com o motivo informado.':'Mensagem enviada.',false);}catch(e){portalMessage(e.message);}finally{if(salePortal)salePortal.busy=false;}}
async function uploadSaleDocuments(files){if(!salePortal||salePortal.busy)return;const chosen=Array.from(files);if(!chosen.length)return;capturePortalForm();salePortal.busy=true;try{for(let n=0;n<chosen.length;n++){const file=chosen[n],type=file.type||(/\.pdf$/i.test(file.name)?'application/pdf':/\.png$/i.test(file.name)?'image/png':/\.jpe?g$/i.test(file.name)?'image/jpeg':'');if(!['application/pdf','image/png','image/jpeg'].includes(type)||file.size<1||file.size>10485760)throw Error('Envie PDF, JPG ou PNG de até 10 MB.');portalMessage(`Enviando documento ${n+1} de ${chosen.length}…`,false);const upload=await api('document-begin',{contractId:salePortal.id,file:{name:file.name,contentType:type,size:file.size}});const response=await fetch(upload.url,{method:'PUT',headers:{'Content-Type':type,'x-upsert':'false'},body:file});if(!response.ok)throw Error('O envio não foi concluído. Confira sua conexão e tente novamente.');await api('document-finish',{contractId:salePortal.id,documentId:upload.id});}await refreshSalePortal();portalMessage('Documentos recebidos. Você já pode enviar a venda para análise.',false);}catch(e){portalMessage(e.message);try{const message=e.message;await refreshSalePortal();portalMessage(message);}catch{}}finally{if(salePortal)salePortal.busy=false;}}
async function finishSaleDocument(id){try{await api('document-finish',{contractId:salePortal.id,documentId:id});await refreshSalePortal();portalMessage('Documento finalizado.',false);}catch(e){portalMessage(e.message);}}
async function downloadSaleDocument(id){try{const result=await api('document-download',{contractId:salePortal.id,documentId:id});const a=document.createElement('a');a.href=result.url;a.target='_blank';a.rel='noopener noreferrer';document.body.appendChild(a);a.click();a.remove();}catch(e){portalMessage(e.message);}}
async function archiveSaleDocument(id){try{await api('document-archive',{contractId:salePortal.id,documentId:id});await refreshSalePortal();portalMessage('Documento retirado da lista. O histórico permanece preservado.',false);}catch(e){portalMessage(e.message);}}
function editPortalDraft(){if(!salePortal)return;const items=portalItems(),c=items[0];if(!c)return;const id=salePortal.id;show(`<h2>Corrigir rascunho</h2><form><div class="formgrid">${field('client','Cliente',c.client,'text','required maxlength="200"')}${field('date','Data da venda / ativação',c.start,'date','required')}${field('due','Primeiro vencimento',c.firstDue||c.start,'date','required')}</div>${items.map((item,n)=>`<section class="panel"><h3>Produto ${n+1}</h3><div class="formgrid">${select('draftProduct'+n,'Produto',state.products.filter(p=>p.company===c.company&&!p.archived).map(p=>[p.id,p.name]),item.product).replace('<select ',`<select onchange="updateDraftProduct(${n},this.value)" `)}${field('draftMonthly'+n,'Mensalidade / venda (R$)',item.monthly,'number','required min="0" max="100000000" step=".01"')}${field('draftSetup'+n,'Implementação (R$)',item.setup,'number','required min="0" max="100000000" step=".01"')}${field('draftParts'+n,'Parcelas da implementação',item.setupParts||1,'number','required min="1" max="60"')}${field('draftFeePaid'+n,'Recebimento do 1º fee · data',item.reportedFeePaidAt||'','date',`max="${localToday()}"`)}${field('draftSetupPaid'+n,'Recebimento da implementação · 1ª parcela',item.reportedSetupPaidAt||'','date',`max="${localToday()}"`)}</div></section>`).join('')}<p id="draftFeedback" role="alert"></p>${actions()}</form>`,async f=>{const error=document.getElementById('draftFeedback');try{await api('update-draft',{contractId:id,version:cloudVersion,sale:{company:c.company,client:f.get('client'),date:f.get('date'),due:f.get('due'),nextFeeDue:c.nextFeeDue||null,billingDay:c.billingDay||null,items:items.map((item,n)=>({product:f.get('draftProduct'+n),setupWaived:item.setupWaived||false,value:Number(f.get('draftMonthly'+n)),setup:Number(f.get('draftSetup'+n)),parts:Number(f.get('draftParts'+n)),feePaidAt:f.get('draftFeePaid'+n)||null,setupPaidAt:Number(f.get('draftSetup'+n))>0?f.get('draftSetupPaid'+n)||null:null}))}});await loadCloud();page='Contratos';render();document.getElementById('modal').close();await openSalePortal(id);portalMessage('Dados corrigidos. Confira os documentos e reenvie para análise.',false);}catch(e){error.textContent=e.message;}});}
function updateDraftProduct(n,id){const p=product(id);if(!p)return;document.getElementById('f_draftMonthly'+n).value=p.baseMonthly??0;document.getElementById('f_draftSetup'+n).value=p.baseSetup??0;}

async function restoreSaleDocument(id){try{await api('document-restore',{contractId:salePortal.id,documentId:id});await refreshSalePortal();portalMessage('Documento restaurado.',false);}catch(e){portalMessage(e.message);}}

const renderBeforeOptimization=render;render=function(){return withRenderFrame(()=>renderBeforeOptimization());};

function saleReceiptSummary(c){const invoices=state.invoices.filter(i=>i.contractId===c.id&&!i.archived),fee=invoices.find(i=>i.kind==='fee'&&i.fee===1),setup=invoices.filter(i=>i.kind==='setup');return `<div class="receipt-summary"><p>1º fee: ${fee?.paidAt?'recebido em '+compactDate(fee.paidAt):'recebimento pendente'}${!fee?.paidAt&&c.reportedFeePaidAt?' · informado pelo vendedor: '+compactDate(c.reportedFeePaidAt):''}</p>${setup.map(i=>`<p>Implementação · parcela ${i.part||1}: ${i.paidAt?'recebida em '+compactDate(i.paidAt):'recebimento pendente'}${!i.paidAt&&i.part===1&&c.reportedSetupPaidAt?' · informado pelo vendedor: '+compactDate(c.reportedSetupPaidAt):''}</p>`).join('')}</div>`;}
function editContractReceipts(id){if(!canManage('Recebíveis'))return;const c=state.contracts.find(c=>c.id===id);if(!c||!canAccess(c.company)||c.archived||c.status!=='Ativo'||c.reviewStatus&&c.reviewStatus!=='approved')return;const rows=state.invoices.filter(i=>i.contractId===id&&!i.archived&&(i.kind==='setup'||i.kind==='fee'&&i.fee===1));show(`<h2>Recebimentos · ${esc(contractCode(c))}</h2><p>Registre separadamente o primeiro fee e cada parcela da implementação.</p><form><div class="formgrid">${rows.map((i,n)=>field('receipt'+n,(i.kind==='fee'?'Primeiro fee':'Implementação · parcela '+(i.part||1))+' · '+money(i.amount),i.paidAt||'','date',`max="${localToday()}" ${i.paidAt?'readonly':''}`)).join('')}</div><p class="small">Datas em branco continuam pendentes. Para corrigir um recebimento confirmado, desfaça-o em Recebíveis; comissões pagas mantêm o bloqueio de segurança.</p>${actions()}</form>`,async f=>{const updates=rows.map((i,n)=>({i,date:f.get('receipt'+n)||null}));for(const {i,date} of updates){if(i.paidAt&&date!==i.paidAt)throw Error('Desfaça o recebimento antes de corrigir a data.');if(date&&(!validDate(date)||date>localToday()||date<c.start))throw Error('Informe datas entre a venda e hoje.');}for(const {i,date} of updates)i.paidAt=date;await save();render();await openSalePortal(id);portalMessage('Recebimentos registrados em datas independentes.',false);});}
